var data = msg.payload;

// Skip plotting if GPS string was invalid and we have no coordinates
if (!data.latitude || !data.longitude) return null;

var icon = "fa-map-marker";
if(data.device_id && data.device_id.includes("hider")) {
    icon = "fa-eye-slash";
} else {
    icon = "fa-search";
}

// Format IMU data for the popup bubble
var acc_str = data.acc ? `[${data.acc[0].toFixed(2)}, ${data.acc[1].toFixed(2)}, ${data.acc[2].toFixed(2)}]` : 'N/A';
var gyr_str = data.gyr ? `[${data.gyr[0].toFixed(2)}, ${data.gyr[1].toFixed(2)}, ${data.gyr[2].toFixed(2)}]` : 'N/A';

msg.payload = {
    name: data.device_id,
    lat: data.latitude,
    lon: data.longitude,
    icon: icon,
    iconColor: data.gps_valid ? "green" : "red",
    extrainfo: "<b>IMU Data</b><br>Accel: " + acc_str + "<br>Gyro: " + gyr_str + "<br><br><b>Raw GPS</b>: " + data.gps
};
return msg;

var p = msg.payload;
if(!p.latitude) return null; // Ignore Unity location data
if(!p.acc) p.acc = [0,0,0];
if(!p.gyr) p.gyr = [0,0,0];
if(!p.mag) p.mag = [0,0,0];

msg.topic = `INSERT INTO telemetry_v3 (device_id, timestamp, gps_valid, latitude, longitude, acc_x, acc_y, acc_z, gyr_x, gyr_y, gyr_z, mag_x, mag_y, mag_z, raw_gps) \
VALUES ('${p.device_id}', datetime(${p.timestamp}, 'unixepoch'), ${p.gps_valid ? 1 : 0}, ${p.latitude}, ${p.longitude}, ${p.acc[0]}, ${p.acc[1]}, ${p.acc[2]}, ${p.gyr[0]}, ${p.gyr[1]}, ${p.gyr[2]}, ${p.mag[0]}, ${p.mag[1]}, ${p.mag[2]}, '${p.gps}')`;
return msg;

var p = msg.payload;
if(!p.latitude) return null; // Ignore Unity location data
if(!p.acc) p.acc = [0,0,0];
if(!p.gyr) p.gyr = [0,0,0];
if(!p.mag) p.mag = [0,0,0];

var table = p.device_id.includes("hider") ? "hider_visualization" : "seeker_visualization";

msg.topic = `INSERT INTO ${table} (timestamp, latitude, longitude, acc_x, acc_y, acc_z, gyr_x, gyr_y, gyr_z, mag_x, mag_y, mag_z) \
VALUES (datetime(${p.timestamp}, 'unixepoch'), ${p.latitude}, ${p.longitude}, ${p.acc[0]}, ${p.acc[1]}, ${p.acc[2]}, ${p.gyr[0]}, ${p.gyr[1]}, ${p.gyr[2]}, ${p.mag[0]}, ${p.mag[1]}, ${p.mag[2]})`;
return msg;

var p = msg.payload;
msg.topic = `INSERT INTO indoor_tracking (device_id, timestamp, x, y, z) VALUES ('${p.device_id}', datetime(${p.timestamp}/1000, 'unixepoch'), ${p.x}, ${p.y}, ${p.z})`;
return msg;
